'use strict';
// A first-visit path that never transfers funds or starts a simulation automatically.
if(!demo.plan&&demo.portfolio.length===2&&demo.portfolio.includes(279342)&&demo.portfolio.includes(150357))demo.portfolio=[371815,127227];
function stationPhotos(s){const first=stationPhoto(s);return first?[first,...(first.gallery||[])]:[]}
function photoStations(){const order=window.ECOCHARGE_STATION_VISUALS?.featuredIds||[371815,167597];return stations.filter(s=>order.includes(s.id)||demo.stationPhotos?.[s.id]).sort((a,b)=>{const ai=order.indexOf(a.id),bi=order.indexOf(b.id);return (ai<0?1000:ai)-(bi<0?1000:bi)})}
function locationCard(s){const photo=stationPhoto(s),count=stationPhotos(s).length;return `<button class="location-card" data-explore-station="${s.id}" aria-label="View ${escapeHtml(s.name)}"><span class="location-image"><img src="${escapeHtml(photo.path)}" alt="${escapeHtml(photo.alt)}" width="1280" height="960" loading="lazy" decoding="async" style="object-position:${escapeHtml(photo.position||'center')}"><span class="photo-count-badge">${photo.kind==='illustration'?'Illustration':count+' '+(count===1?'photo':'photos')}</span></span><span class="location-card-body"><strong>${escapeHtml(s.city)}, ${s.state}</strong><span>${escapeHtml(s.name.replace(/\s*\([^)]*\)\s*$/,''))}</span><small>${s.ports} DC ports · ${s.maxKw||'—'} kW max ${icon('arrow')}</small></span></button>`}
function renderPhotoExplorer(){let section=$('#photo-explorer');if(!section){section=document.createElement('section');section.id='photo-explorer';section.className='photo-explorer';$('#map-section').before(section)}section.hidden=tab!=='dashboard';const rows=photoStations();if(!rows.length){section.hidden=true;return}const total=rows.reduce((n,s)=>n+(stationPhoto(s).kind==='illustration'?0:stationPhotos(s).length),0);section.innerHTML=`<div class="explorer-heading"><div><h2>Explore real locations</h2><p>${rows.length} locations · ${total} real photos + marked illustrations.</p></div><button class="text-button" data-action="photo-directory">View all ${icon('arrow')}</button></div><div class="location-rail" aria-label="Station locations with photos">${rows.slice(0,6).map(locationCard).join('')}</div><div class="gallery-footer"><button class="text-button" data-action="explore-map">Explore all stations ${icon('map')}</button><div class="gallery-tools"><button data-rail-move="-1" aria-label="Previous locations">←</button><button data-rail-move="1" aria-label="Next locations">→</button></div></div>`}
actions['photo-directory']=()=>{openModal('<h2>Explore 50 station locations</h2><p>Real location photos have source credits. Other cards are clearly marked as concept illustrations.</p><input class="photo-filter" id="photo-filter" type="search" aria-label="Search station locations" placeholder="City, state or station name…"><div class="gallery-count" role="status" id="gallery-count"></div><div class="location-gallery" id="location-gallery"></div>');filterPhotoGallery()};
function filterPhotoGallery(){const q=($('#photo-filter')?.value||'').toLowerCase().trim(),rows=photoStations().filter(s=>(s.city+' '+s.state+' '+s.name+' '+s.id).toLowerCase().includes(q));$('#gallery-count').textContent=rows.length+' matching locations';$('#location-gallery').innerHTML=rows.length?rows.map(locationCard).join(''):'<div class="empty-state">No locations match. Try another city or use the full station map.</div>'}
document.addEventListener('input',e=>{if(e.target.id==='photo-filter')filterPhotoGallery()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-rail-move]');if(b){const rail=$('.location-rail');rail.scrollBy({left:Number(b.dataset.railMove)*rail.clientWidth*.85,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}});
actions['explore-map']=()=>{tab='map';renderClientTab();setTimeout(()=>actions['fit-map'](),150);window.scrollTo({top:0,behavior:'instant'})};
actions['demo-guide']=()=>openModal(`<h2>Try the complete demo</h2><p>Explore the product with sample funds. No payment is collected.</p><ol class="demo-guide-list"><li><strong>Choose a real location</strong><span>Open a station, review its photo and address, then select it for a demo investment.</span><button class="button secondary" data-action="guide-map">Explore stations ${icon('map')}</button></li><li><strong>Build a demo plan</strong><span>Compare 1, 3, 5 or 10 reference stations. The weekly rate applies once to the total capital.</span><button class="button secondary" data-action="tariffs">Compare plans ${icon('zap')}</button></li><li><strong>Try a weekly accrual</strong><span>After applying a plan, use “Simulate week” to record a test event. View the balance, history and printable agreement.</span></li></ol><div class="modal-note">The Staff console lets you edit the client profile and plan, approve demo requests and reply to messages. Demo data stays in this browser; other visitors start with their own sample account.</div><button class="button primary" data-action="guide-manager">Explore manager workspace ${icon('users')}</button>`);
actions['guide-map']=()=>{$('#modal').close();actions['explore-map']()};
actions['guide-manager']=()=>{$('#modal').close();setRole('admin');adminTab='overview';renderAdmin()};
const planBarBeforeGuide=renderPlanBar;
renderPlanBar=function(){planBarBeforeGuide();let guide=$('#demo-walkthrough');if(!guide){guide=document.createElement('div');guide.id='demo-walkthrough';guide.className='demo-walkthrough';$('#plan-shortcut').after(guide)}guide.hidden=tab!=='dashboard';guide.innerHTML=`<span>${icon('shield')} ${demo.plan?'Demo plan ready. Try one week and review your history.':'Choose a station. Pick a plan. Try one demo week.'}</span><button data-action="demo-guide">How it works ${icon('arrow')}</button>`;renderPhotoExplorer()};
const photoBeforeExplorer=updateStationPhoto;
updateStationPhoto=function(s){photoBeforeExplorer(s);const image=$('.station-photo img');if(image){image.loading='lazy';image.decoding='async'}renderPhotoExplorer()};
const navigationBeforeMobile=renderNav;
renderNav=function(){navigationBeforeMobile();const active=$('.main-nav .active');if(active)active.setAttribute('aria-current','page');const skip=$('#skip-content');if(skip)skip.href=role==='admin'?'#admin-view':'#client-view';const url=new URL(location);url.searchParams.set('view',role);url.searchParams.set('tab',role==='admin'?adminTab:tab);history.replaceState({},'',url)};
const clientTabBeforeMobile=renderClientTab;
renderClientTab=function(){clientTabBeforeMobile();renderPhotoExplorer();const heading=$('#client-page-title');if(heading)heading.textContent=({dashboard:'Investor overview',map:'Charging station map',assets:'Your reference stations',documents:'Documents and support',tariffs:'Weekly demo plans'})[tab]||'Investor portal'};
const roleBeforeMobile=setRole;
let routeRestored=false;
setRole=function(next){if(!routeRestored){const t=new URL(location).searchParams.get('tab');if(next==='admin'&&['overview','clients','requests','stations','tariffs','plan'].includes(t))adminTab=t;if(next!=='admin'&&['dashboard','map','assets','documents','tariffs'].includes(t))tab=t;routeRestored=true}roleBeforeMobile(next)};
const openModalBeforeMobile=openModal;
openModal=function(html){openModalBeforeMobile(html);const heading=$('#modal-content h2');if(heading){heading.id='dialog-title';$('#modal').setAttribute('aria-labelledby','dialog-title')}$('#modal').scrollTop=0};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.exploreStation){selectStation(b.dataset.exploreStation);actions.station()}if(b.dataset.tab||b.dataset.managerView)window.scrollTo({top:0,behavior:'instant'})});
document.body.insertAdjacentHTML('afterbegin','<a id="skip-content" class="skip-link" href="#client-view">Skip to content</a>');
$('#client-view').insertAdjacentHTML('afterbegin','<h1 id="client-page-title" class="sr-only">Investor overview</h1>');
$('#client-view').setAttribute('tabindex','-1');$('#admin-view').setAttribute('tabindex','-1');
$('#modal').addEventListener('close',()=>{if(document.activeElement===$('#skip-content'))$(role==='admin'?'#admin-view':'#client-view').focus({preventScroll:true})});
$('.prototype-bar>span').insertAdjacentHTML('beforeend','<button class="demo-help" data-action="demo-guide" aria-label="How to use the demo">?</button>');
renderPhotoExplorer();

// Keep dialog controls within reach and separate scrolling content from actions.
const modalBeforeSheet=openModal;
openModal=function(html){$('#modal>.dialog-actions')?.remove();$('#modal').classList.remove('photo-lightbox');modalBeforeSheet(html);document.documentElement.classList.add('modal-is-open');document.body.classList.add('modal-is-open');$('#modal-content').scrollTop=0};
$('#modal').addEventListener('close',()=>{document.documentElement.classList.remove('modal-is-open');document.body.classList.remove('modal-is-open');$('#modal>.dialog-actions')?.remove()});
let activeStationPhoto=0;
function photoCredit(p){if(p.kind==='illustration')return `<div class="illustration-caption"><strong>Concept illustration · not a station photograph</strong><p>This artwork does not show the actual site layout or equipment. The address and station data come from the public directory.</p><a href="${escapeHtml(p.source)}" target="_blank" rel="noopener">Public station record ↗</a></div>`;return `<details class="photo-source-details"><summary>Photo date, source & license</summary><p>${p.dateTaken?'Photographed '+escapeHtml(p.dateTaken)+'. ':p.dateUploaded?'Published '+escapeHtml(p.dateUploaded)+'. Capture date not listed. ':''}${escapeHtml(p.credit)}</p><p><a href="${escapeHtml(p.source)}" target="_blank" rel="noopener">Original source ↗</a>${p.licenseUrl?' · <a href="'+escapeHtml(p.licenseUrl)+'" target="_blank" rel="noopener">License ↗</a>':''}</p><p>Displayed crop. A photo does not show current availability.</p></details>`}
function renderStationGallery(){const photos=stationPhotos(selected);if(!photos.length)return;const p=photos[activeStationPhoto]||photos[0],area=$('#modal-content .station-dialog-photo');if(!area)return;area.innerHTML=`<button class="station-gallery-image" data-photo-expand="true" aria-label="Enlarge station image"><img src="${escapeHtml(p.path)}" alt="${escapeHtml(p.alt)}" width="1280" height="960" style="object-position:${escapeHtml(p.position||'center')}" data-station-photo="${selected.id}"><span>${p.kind==='illustration'?'View illustration':'View photo'} · ${activeStationPhoto+1} / ${photos.length} ↗</span></button>${photos.length>1?'<div class="station-photo-thumbs" aria-label="Location photo angles">'+photos.map((p,i)=>`<button data-photo-index="${i}" aria-label="View photo ${i+1}" aria-pressed="${i===activeStationPhoto}"><img src="${escapeHtml(p.path)}" alt="" width="64" height="48" loading="lazy"></button>`).join('')+'</div>':''}${photoCredit(p)}`}
const stationBeforeSheet=actions.station;
actions.station=function(){activeStationPhoto=0;stationBeforeSheet();if(!selected)return;renderStationGallery();const primary=$('#modal-content [data-action="invest-selected"]');if(primary){const footer=document.createElement('div');footer.className='dialog-actions';primary.innerHTML=(demo.plan?.stationIds.includes(selected.id)?'Edit demo plan':'Build demo plan')+' '+icon('arrow');footer.append(primary);footer.insertAdjacentHTML('beforeend',`<button class="button secondary" data-contact-topic="station">${icon('chat')} Ask my manager</button>`);$('#modal').append(footer)}};
function showStationLightbox(index=0){const photos=stationPhotos(selected);if(!photos.length)return;activeStationPhoto=(index+photos.length)%photos.length;const p=photos[activeStationPhoto];openModal(`<h2>${escapeHtml(selected.city)}, ${selected.state}</h2><img class="lightbox-image" src="${escapeHtml(p.path)}" alt="${escapeHtml(p.alt)}" width="1280" height="960"><div class="lightbox-controls"><button class="button secondary" data-lightbox-step="-1" ${photos.length<2?'disabled':''} aria-label="Previous photo">←</button><span>${p.kind==='illustration'?'Concept illustration':'Photo '+(activeStationPhoto+1)+' of '+photos.length}</span><button class="button secondary" data-lightbox-step="1" ${photos.length<2?'disabled':''} aria-label="Next photo">→</button></div>${photoCredit(p)}<button class="button secondary" data-action="station">Back to station details</button>`);$('#modal').classList.add('photo-lightbox')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.photoIndex!==undefined){activeStationPhoto=Number(b.dataset.photoIndex);renderStationGallery()}if(b.dataset.photoExpand)showStationLightbox(activeStationPhoto);if(b.dataset.lightboxStep)showStationLightbox(activeStationPhoto+Number(b.dataset.lightboxStep))});
document.addEventListener('focusin',e=>{if(e.target.matches('input,textarea,select')&&matchMedia('(max-width:600px)').matches)document.body.classList.add('keyboard-active')});
document.addEventListener('focusout',()=>{setTimeout(()=>{if(!document.activeElement.matches('input,textarea,select'))document.body.classList.remove('keyboard-active')},0)});
// Keep the mainland readable. State search still covers Hawaii and all directory records.
actions['fit-map']=()=>{if(!map)return;const rows=filteredStations();if(!rows.length)return;map.stop();map.invalidateSize({pan:false});if(filter==='all'&&!$('#state-filter').value&&!$('#station-search').value.trim())map.fitBounds([[24.8,-124.7],[49,-66.8]],{paddingTopLeft:[25,110],paddingBottomRight:[25,70],animate:false});else map.fitBounds(rows.map(s=>[s.lat,s.lng]),{paddingTopLeft:[30,115],paddingBottomRight:[30,65],maxZoom:8,animate:false})};
document.querySelector('[data-action="fit-map"]').setAttribute('aria-label','Fit US mainland or filtered stations');
